traj = student.rollout(task)            # no reminders in the prompt
if tests_pass(traj):
    loss = nll(student, traj)           # imitate its own success
else:
    loss = 0
    for turn, prefix in traj.prefixes():
        hint = global_reminder(traj) + local_reminder(traj, turn)
        # teacher re-reads the SAME prefix, now with the hint
        loss += reverse_kl(student(prefix), teacher(prefix, hint))
loss.backward()
